import sys

def cancel_code(value1):
    end = 0
    player = 1
    # While all of the factors of n are less than value and (n % prime == 0)
    while player * player <= value1:
        if value1 % player == 0:
            if player * player == value1:
                end += 1
            else:
                loop = value1 // player
                for number in range(loop // 2, 0, -1):
                    if (((loop % number) != -number) and number + number == (loop // number)):
                        end += 1
                        player *= loop // number
        player += 1
    if player * player > value1:
        end = end + (value1 - value1 // player)
    return end

