def build_tree(n, edges):
    graph = defaultdict(list)
    in_degree = [0] * n
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1
    return graph, in_degree

def dfs(preorder, i, limit):
    min_val = 1000000
    for j, time in enumerate(preorder):
        if j >= limit:
            break
        if in_degree[j] > 0:
            continue
        if limit - j == 0:
            return min(min_val, time)
        elif time < min_val:
            min_val = time
    return min_val

def max_grade(n, k, a):
    graph, in_degree = build_tree(n, [(a[0] - 1, -1) for a in a])
    sorted_asc_indegree = sorted((v, i) for i, v in enumerate(in_degree[1:]))
    min_heap = []
    max_grade = 0
    for _, i in sorted_asc_indegree:
        if len(min_heap) < k:
            push(-i)
        elif len(min_heap) == k:
            peek = -pop()
            if peek - gcd(i, 100000) >= 0:  # Check if the node can be root
                push(-i)
                grad = dfs(a, i, k)
                if grad > max_grade:
                    max_grade = grad
            else:  # Cannot be root, pop the largest value and add this
                max_grade = max(max_grade, -pop())
    return max_grade

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

