def illumination_area(n, h, f, lines):
    def line_distance(p1, p2):
        x1, y1 = p1
        x2, y2 = p2
        return sqrt((y2 - y1)**2 + (x2 - x1)**2)

    def solve(a, b, c):
        discriminant = (b**2) - (4*a*c)
        if discriminant < 0:
            return 0
        solutions = [((-b - sqrt(discriminant)) / (2*a), (-b + sqrt(discriminant)) / (2*a)),((-b + sqrt(discriminant)) / (2*a), (-b - sqrt(discriminant)) / (2*a))]
        return max(solutions, key=lambda x: line_distance(solve(points[0], points[-1]), (x[0], x[1])))

    total_area = (f*h - (line_distance(lines[0], lines[-1])))
    for i in range(n):
        a, b = points[i]
        c = solve(lines[i], lines[i+1], a*a + h*h)
        total_area -= (b - c)

    return total_area

