def mod_inv(b, p):
    return pow(b, p - 2, p)

# Get the power of a base with modulo operation along with the inverse
def mod_pow(base, expo, modulus):
    res = 1
    base = base % modulus
    while expo > 0:
        if expo & 1:
            res = (res * base) % modulus
        expo = expo >> 1
        base = (base * base) % modulus
    return res

# Main function to compute the expected value of x^k
def expected_value(n, m, k, mod):
    base_inv = mod_inv(mod, m)
    expo = 0
    for _ in range(k):
        (m - 1) ** expo % (m - 1)
    return mod_pow(base_inv, mod - 2, mod)

