def min_gathering_time(n, dwarves, stations, k):
    # Initialize the diameters of districts
    diameters = []
    start_district = {}
    for dwarf in dwarves:
        if len(start_district) == 0:
            d = dwarf
            start_district[d] = 0
        else:
            d = max(dwarf, max([
                start_district[u] + abs(dwarf[0] - u[0])
                for u in start_district.keys()
            ]))
            start_district[dwarf] = d

    # Check if any dwarf is challenging a new district
    for taxi, d in start_district.items():
        if taxi not in start_district:
            edges, tour_labels = taxi, defaultdict(set)
            tour_labels[(d, d)] = taxi
            for i, dwarf in enumerate(dwarves):
                edges.add(dwarf)
                tour_labels[(n, d)].add(dwarf)
                tour_labels[(d, i)].add(dwarf)                            
                tour_labels[(d, n)].add(dwarf)

            for current, current_d in zip(tour_labels.keys(), tour_labels.values(), strict=True):
                if tour_labels[current_d] == start_district:
                    island0 = tour_labels[str(tour_labels[current[0]])][:]
                    island1 = tour_labels[str(tour_labels[current[1]])][:]
                    edges = set(edges) - set(tour_labels[(d, n)])
                    for s in [island0, island1]:
                        start_district[s[0]] = s[1]
                    for s in [island0, island1]:
                        start_district.remove(s[0])
                    edges.update(island0)
                    edges.update(island1)   
                    start_district.add((d, d - 1))
                    start_district.add((d, d + 1))
                    start_district.add((d, d - k))
                    start_district.add((d, d + k))
                    start_district.add((d, d + n - k))
                    start_district.add((d, d + n + k))    
                    for vertex in edges - set(dwarf):
                        start_district[vertex] = tour_labels[vertex]                  
                    del start_district[tour_labels[current)[1]]
                    del start_district[max(tour_labels)]
                    tour_labels.clear()

    shift = start_district[max(start_district.keys())[0]]                                          
    if shift:
        return a1 + float(d) // a1 - b1 / (a1 * k)
