# dp[x][i] := the exp value when there are i misplaced cards,
#     and once x cards are misplaced, in how many ways get i misplaced cards
@lru_cache(None) 
def dp(x, cur):
    if x == 1:
        return cur, 1

    result = Fraction(1, len(results))
    # achieve a specific newPosition with remaining cards
    for key in results:    
        # If the ith character is not at i in newPosition when this index has value key
        if key & results & 1<<i:
            continue

        result *= dp(cur + (key & ~results) % MOD, key)[1]

    return result

@lru_cache(None)
def fi():
    return Fraction(1, inf).mul(num_prefix_planted(inf) % MOD)

@lru_cache(None)
def f(results):
    return Fraction((results ^ results) % MOD if results else 0, modulo)

@lru_cache(None)
def fib(x, steps):
    if x == 0:
        return 0
    more = fi()
    if steps > x:
        return more
    if steps < x:
        return fib(x - 1, steps + 1) + f(x - steps, steps)
    return fib(x - 1, steps) + more * fib(x, steps / 2)

