def mod_fibonacci(n, m):
    if n == 1:
        return [1, 0]
    else:
        f_of_m = [1, 0]
        while n > 1:
            f_of_m = [f_of_m[1], f_of_m[0] + f_of_m[1]]
            n -= 1
        return f_of_m

def digit_sum(num):
