def mod_function(n, m, k):
    mod_fbn = mod_fibonacci(n, m)
    fbn = mod_fbn[1]
    if k == 1:
        return mod_fbn[1] % m
    elif k == 2:
        return (mod_fbn[0] + fbn * mod_fbn[1]) % m
    else:
        fn = 0
        for i in range(2, n + 1):
            fn += (i * mod_fbn[0]) % m
        return (fn + fbn * (mod_fbn[1] ** (k - 2))) % m

