def euler_totient(n):
    res = n
    i = 2
    while i <= n and i < res:
        if (res % i) == 0:
            res //= i
            while (res % i) == 0:
                res //= i
        i += 1
    return int(res)

@lru_cache(None)
def find_days(month_days, day):
    if month_days == 0:
        return euler_totient(day)
    return (month_days - 1) * find_days(month_days - 1, day)

def solve(n, k):
    months = defaultdict(int)
    for i in range(1, 13):
        for j in range(1, gcd(i, 12)):
            if gcd(i, j) in months:
                continue
            left_days = 2 * find_days(31, j)
            mid_days = 2 * find_days(30, j)
            right_days = 2 * find_days(31, j + gcd(i, 12))
            curves = sum(euler_totient(p)
                         for p in range(min(max(i, 1), 49), max(min(i + 1, 12), 1)) if gcd(12, p))
            if 12 - i == 3:
                curves += left_days
            elif 12 - i == 4:
                curves += mid_days
            else:
                curves += right_days
            if k <= curves:
                months[i] += 1

    total = 0
    for i in months.values():
        total = (total + i) % 998244353
    for i in range(1, 13):
