from typing import List

def max_grade(n: int, k: int, tasks: List[int], edges: List[List[int]]) -> int:
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u - 1].append(v - 1)
        graph[v - 1].append(u - 1)

    if n == 1:
        return max(tasks[0], 0)

    diameter, parent, depth = 0, 0, 0
    stack, visited = [(0, 0)], set()

    while stack:
        u, d = stack.pop()
        visited.add(u)
        if u:
            if u == parent:
                diameter = max(diameter, d)
            else:
                stack.append((u, d + 1))
                visited.add(u)

        if len(visited) == n:
            visited.remove(parent)
            for i, u in enumerate(visited):
                if visited.isdisjoint(graph[i]):
                    visited = visited[:i] + visited[i + 1:]
                    stack.append((0, depth - d))
                    parent = 0
                    visited.append(u)
                    stack.append((u, 1))
                    visited.remove(u)
                    depth = depth + 1
                    break

    min_time = float('inf')

    for i in range(n):
        if i not in visited:
            for j in range(i, n):
                if sum(tasks[max(i, j):j + n - i - 1]) + diameter >= k + tasks[min(i, j)]:
                    min_time = min(min_time, max(tasks[max(i, j):j + n - i - 1]) + diameter + tasks[min(i, j)])

    return min_time
