def super_function(N, K, M):
    MOD = M
    primes = [(2, 3)]
    prime_count = 2
    current_prime = 2
    for prime in range(3, N+1, 2):
        if all(gcd(prime, p) != 1 for p in primes):
            primes.append(prime)
            prime_count += 1
    def inverse(x, MOD):
        if x == 1:
            return 1
        for i in range(prime_count):
            if (x * pow(i+2, i+2, MOD-2) % MOD) == 1:
                return i+2
        return None

    result = 0
    for prime in primes:
        cycles = sum(map(lambda x: prime**x % MOD, range(1, K+1)))
        for exponent in range(1, K+1):
            cycles += reverse_and_negation(prime, exponent, MOD)
            cycles %= MOD
        result += cycles % MOD
        result %= MOD
    return result

