                        if (last_hull[0] - x) * temp_point[1] > (x - temp_point[0]) * (last_hull[1] - temp_point[1]):
                            self.hull.append(last_hull)
                            self.hull.append(temp_point)
                        else:
                            break

    def belongs_to_hull(self, x: float, y: float) -> str:
        if len(self.hull) < 3:
            return "NO" if not self.hull else "YES"
        else:
            # If adding the current point would create a closed polygon, it's in the hull
            test_addition = list(self.hull)
            test_addition.append((x, y))
            self.add_point(0, math.inf)
            test_addition.append((x, 0))
            self.add_point(2 * math.inf, 0)
            hull = self.hull
            for i in range(len(hull)):
                prev, vertex = hull[i], hull[(i + 1) % len(hull)]
                if (vertex[0] - prev[0]) * (y - prev[1]) == (x - prev[0]) * (y - vertex[1]):
                    del hull[i]
                else:
                    del hull[(i + 1) % len(hull)]
            return "YES" if self.hull else 'NO'

def solve_queries(q: int, queries: List[List[str]]) -> List[str]:
    ch = ConvexHull()
    for query in queries[1:] + queries[:1]:
        if query[0] == '1':
