import math

def super_function(N, K, M):
    primes = {value: (value, False) for value in range(2, N+1)}

    for divisor in range(2, int(math.sqrt(N)) + 1):
        if primes[divisor][1]:
            continue

        current_prime = divisor
        power = 1
        while current_prime * current_prime <= N:
            old_prime = current_prime ** power
            while old_prime <= N:
                new_prime, is_prime = primes[old_prime]
                primes[old_prime] = (old_prime, is_prime and (current_prime in (2, 3)))
                current_prime = new_prime
                if is_prime:
                    primes[new_prime-1] = False
                    primes[new_prime+current_prime-1] = ((new_prime+current_prime-1, False) if (N+1)%new_prime == 0 else (new_prime*(new_prime+current_prime-1), True))
                power += 1
            current_prime += 1

    res = 0
    for i in range(1, N+1):
        if primes[i][1] and i < N // (K + 1):
            residual_prime = i % (K + 1)
            exponent = (1 + residual_prime - 1) * (K + 1) // i

            if max(M % (i ** (K + 1)), M % (i ** (K + 1) // i) - M % (K) * i) % M > M:
                continue
            if max(M % (i ** (K + 1) - i), M % (i ** (K + 1) // i) - M % (K) * i) % M > M:
                continue

            res += i ** (K + 1)
            res %= M

    return res

