                    stack.append((triangle[2], triangle[0]))
                    stack.append((triangle[0], triangle[1]))
        if y < point[1]:
            stack[-1] = point
        else:
            stack[-1] = point
            stack = stack[:bisect.bisect_right(stack, reversed(stack))]

