class ConvexHull:
    def __init__(self):
        self.hull = []

    def add_point(self, x, y):
        self.hull.append((x, y))
        self.hull.sort()

    def contains_point(self, x, y):
        for i in range(len(self.hull)):
            midx, midy = self.hull[i]
            v1 = (self.hull[(i-1)%len(self.hull)][0] - midx, self.hull[(i-1)%len(self.hull)][1] - midy)
            v2 = (self.hull[(i+1)%len(self.hull)][0] - midx, self.hull[(i+1)%len(self.hull)][1] - midy)
            x2y1 = (x - midx, y - midy)
            if v1[1] * x2y1[0] == v2[1] * x2y1[0] and v1[0] * x2y1[1] <= v1[1] * x2y1[1]:
                return "YES"
        return "NO"

