from math import gcd
from functools import reduce

# Function to compute the greatest common divisor
def lcm(a, b):
    return a * b // gcd(a, b)

# Function to compute the least common multiple of a list of numbers
def lcm_gcd(l):
    final = reduce(lcm, l)
    lcm = 1
    for x in l:
        lcm = (lcm * x) // gcd(lcm, x)
    return lcm

# Compute the sum of the first k positive integers
def sum_of_first_k(k):
    return int(k * (k + 1) / 2)

def solve(x):
    total_sum = 0
    # Iterate over the possible divisors
    for i in range(1, int(x ** 0.5) + 1):
        if x % i == 0:
            fraction = sum_of_first_k(int(x / i))
            total_sum += fraction
    return total_sum

A = int(input())
result = lcm_gcd([1, A])
output = solve(result)
print(output)
